// parcelUniqueKeys are the conflict targets of Parcel's unique keys, and
// the assignment of the update an upsert that sets nothing names, which its
// WHERE FALSE never runs (sqlutil.UniqueKey, D79); the read of the rows
// that hold keys, which an upsert reads back when it leaves them as they
// were, empty for a key over an expression, and that key's read of the row
// that holds one input's value of it, empty for a key over columns; and the
// key's columns as a batch insert's cells name them (D89).
var parcelUniqueKeys = map[ParcelUniqueKey]struct {
	conflict, keep, rows, held string
	columns                    []string
}{
	ParcelUniqueById:           {`(id)`, `id = parcel.id`, `SELECT "id", "tracking_code", "weight_grams", "note", "version" FROM parcel WHERE (id) IN (%s)`, ``, []string{`id`}},
	ParcelUniqueByTrackingCode: {`(tracking_code)`, `tracking_code = parcel.tracking_code`, `SELECT "id", "tracking_code", "weight_grams", "note", "version" FROM parcel WHERE (tracking_code) IN (%s)`, ``, []string{`tracking_code`}},
}

// parcelKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func parcelKeyOf(on ParcelUniqueKey, row *types.Parcel) (string, bool) {
	switch on {
	case ParcelUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	case ParcelUniqueByTrackingCode:
		return upsertKeyText(upsertKeyValue(row.TrackingCode, false))
	}
	return "", false
}

