// UpsertOne inserts input, or, when a row already holds its value of the
// unique key on, applies update to that row instead, and returns the row
// (D79). The insert writes what CreateOne writes and the update what
// UpdateOne writes, updated_at and updated_by among it, but an update that
// sets no field leaves the row as it is.
func (r *ParcelRepository) UpsertOne(ctx context.Context, input *types.Parcel, on ParcelUniqueKey, update *ParcelUpdate) (*types.Parcel, error) {
	result, err := r.UpsertOneResult(ctx, input, on, update, nil)
	if err != nil {
		return nil, err
	}
	return result.Row, nil
}

// UpsertOneResult is UpsertOne, and what it did with the row: inserted it,
// updated the row that held the key, or left that row as it was (D89).
// With opts.OnlyIfChanged it updates the row only when a field the update
// sets differs from what the row holds, which it reads back otherwise. One
// whose update sets no field updates nothing, so the row keeps its version
// and no trigger fires, and reads the row back. A write that
// may take more than one statement runs in a transaction of its own when
// none is open.
func (r *ParcelRepository) UpsertOneResult(ctx context.Context, input *types.Parcel, on ParcelUniqueKey, update *ParcelUpdate, opts *UpsertOptions) (UpsertResult[*types.Parcel], error) {
	var none UpsertResult[*types.Parcel]
	key, ok := parcelUniqueKeys[on]
	if !ok {
		return none, fmt.Errorf("orm: Parcel has no unique key %q", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if opts.OnlyIfChanged && key.rows == "" {
		return none, upsertExpressionKey("UpsertOneResult", "Parcel", string(on))
	}
	if update == nil {
		update = &ParcelUpdate{}
	}
	write := func(repo *ParcelRepository) (UpsertResult[*types.Parcel], error) {
		result, err := repo.upsertRow(ctx, input, on, update, opts.OnlyIfChanged)
		if err != nil {
			return none, err
		}
		return *result, nil
	}
	if !opts.OnlyIfChanged && parcelUpdateSetsField(update) {
		return write(r)
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (UpsertResult[*types.Parcel], error) {
		return write(&ParcelRepository{tx: tx, txDB: r.database()})
	})
}

// parcelUpdateSetsField reports whether update sets a field, a value or a
// null: UpdatedBy alone sets none, but stamps the row an update that sets
// one changes.
func parcelUpdateSetsField(update *ParcelUpdate) bool {
	return update != nil && *update != (ParcelUpdate{UpdatedBy: update.UpdatedBy})
}

// upsertRow is UpsertOneResult on the repository's connection: the upsert,
// a read of the row it left as it was, when the update sets no field or
// only if changed, and the second statement of an encrypted field.
func (r *ParcelRepository) upsertRow(ctx context.Context, input *types.Parcel, on ParcelUniqueKey, update *ParcelUpdate, onlyIfChanged bool) (*UpsertResult[*types.Parcel], error) {
	key := parcelUniqueKeys[on]
	// Set audit fields

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := parcelUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Required field: trackingCode
	fields = append(fields, `tracking_code`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.TrackingCode)
	// Required field: weightGrams
	fields = append(fields, `weight_grams`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.WeightGrams)
	// Optional field: note - only add if set
	{
		if !reflect.ValueOf(input.Note).IsZero() {
			fields = append(fields, `note`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.Note)
		}
	}
	// Required field: version
	fields = append(fields, `version`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Version)

	// Handle relationship foreign key columns

	// Build the update of the row the key conflicts with, its placeholders
	// numbered after the insert's
	var setClauses, compareCurrent, compareNext []string
	if update.TrackingCode != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`tracking_code = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `parcel.tracking_code`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.TrackingCode)
	}
	if update.WeightGrams != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`weight_grams = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `parcel.weight_grams`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.WeightGrams)
	}
	if update.Note != nil && update.NoteSetNull {
		return nil, fmt.Errorf("note cannot be updated with both value and null assignment")
	}
	if update.NoteSetNull {
		setClauses = append(setClauses, `note = NULL`)
		compareCurrent = append(compareCurrent, `parcel.note`)
		compareNext = append(compareNext, `NULL`)
	} else if update.Note != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`note = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `parcel.note`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Note)
	}
	if update.Version != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`version = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `parcel.version`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Version)
	}

	assigned := len(setClauses)
	if assigned == 0 {
		// An update that sets no field compares none, so its WHERE is FALSE:
		// it leaves the row as it is, its version, stamps and history all,
		// and reads it back below.
		setClauses = append(setClauses, key.keep)
	} else {
		// Set updated_at

		// Set updated_by

		// Each fence the update's columns advance moves on by one (D118).
		setClauses = append(setClauses, fenceBumps(parcelFences, setClauses)...)

	}

	query := fmt.Sprintf(
		`INSERT INTO parcel (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "tracking_code", "weight_grams", "note", "version", (xmax = 0) AS _inserted`,
		strings.Join(fields, ", "),
		"("+strings.Join(placeholders, ", ")+")",
		key.conflict,
		strings.Join(setClauses, ", "),
		upsertWhere(``, compareCurrent, compareNext, onlyIfChanged || assigned == 0),
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}
	var inserted bool
	scanned, err := r.scanReturned(row, &inserted)
	var upserted *UpsertResult[*types.Parcel]
	switch {
	case err == nil:
		status := UpsertUnchanged
		if inserted {
			status = UpsertInserted
		} else if assigned > 0 {
			status = UpsertUpdated
		}
		upserted = &UpsertResult[*types.Parcel]{Row: scanned, Status: status}
	case err != pgx.ErrNoRows:
		return nil, fmt.Errorf("failed to scan result: %w", err)
	case !onlyIfChanged && assigned > 0:
		// The row the key conflicts with is soft-deleted.
		return nil, ErrNotFound
	default:
		// The row the key conflicts with, which the update sets no field of
		// or which already held the update's values, read back by its key:
		// a soft-deleted one is ErrNotFound.
		keyValues, ok := upsertCellValues(upsertCells(fields, values), key.columns)
		if !ok {
			return nil, fmt.Errorf("no Parcel row holds an unset %s: %w", string(on), ErrNotFound)
		}
		found, err := r.heldOfKey(ctx, on, keyValues, input)
		if err != nil {
			return nil, err
		}
		upserted = &UpsertResult[*types.Parcel]{Row: found, Status: UpsertUnchanged}
	}
	return upserted, nil
}

// UpsertMany inserts each input, or, when a row already holds its value of
// the unique key on, sets each field update names of that row to the value
// the input would have inserted, and returns each input's row and what it
// did with it, in the inputs' order (D89). One statement writes a batch of
// rows, opts.Batch or as many as Postgres binds the parameters of, and more
// rows take a statement per batch, in one transaction; a write that may
// take more than one statement runs in a transaction of its own when none
// is open. One whose update names no field updates nothing, so each row
// that holds a key keeps its version and no trigger fires, and reads those
// rows back. Two inputs of one batch that hold one key fail
// the statement, and a key over an expression, whose rows the statement's
// cannot be matched to the inputs by, is refused.
func (r *ParcelRepository) UpsertMany(ctx context.Context, inputs []*types.Parcel, on ParcelUniqueKey, update ParcelFields, opts *UpsertOptions) ([]UpsertResult[*types.Parcel], error) {
	key, ok := parcelUniqueKeys[on]
	if !ok {
		return nil, fmt.Errorf("orm: Parcel has no unique key %q", string(on))
	}
	if key.rows == "" {
		return nil, upsertExpressionKey("UpsertMany", "Parcel", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if update.Id {
		return nil, fmt.Errorf("orm: UpsertMany of Parcel sets the fields an update sets, not id")
	}
	batch, err := upsertBatch("Parcel", opts.Batch, 13106)
	if err != nil {
		return nil, err
	}
	if len(inputs) == 0 {
		return []UpsertResult[*types.Parcel]{}, nil
	}
	if len(inputs) <= batch && !opts.OnlyIfChanged && update != (ParcelFields{}) {
		return r.upsertBatches(ctx, inputs, on, update, batch, false)
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]UpsertResult[*types.Parcel], error) {
		return (&ParcelRepository{tx: tx, txDB: r.database()}).upsertBatches(ctx, inputs, on, update, batch, opts.OnlyIfChanged)
	})
}

// upsertBatches is UpsertMany on the repository's connection, a batch at a
// time: each batch's statement, a read of the rows it left as they were,
// when update names no field or only if changed, and the second statement
// of each encrypted field.
func (r *ParcelRepository) upsertBatches(ctx context.Context, inputs []*types.Parcel, on ParcelUniqueKey, update ParcelFields, batch int, onlyIfChanged bool) ([]UpsertResult[*types.Parcel], error) {
	key := parcelUniqueKeys[on]

	// Set audit fields

	// Each field update names takes the value the input would have
	// inserted, which an upsert only if changed compares with the row's.
	var setClauses, compareCurrent, compareNext []string
	if update.TrackingCode {
		setClauses = append(setClauses, `tracking_code = EXCLUDED.tracking_code`)
		compareCurrent = append(compareCurrent, `parcel.tracking_code`)
		compareNext = append(compareNext, `EXCLUDED.tracking_code`)
	}
	if update.WeightGrams {
		setClauses = append(setClauses, `weight_grams = EXCLUDED.weight_grams`)
		compareCurrent = append(compareCurrent, `parcel.weight_grams`)
		compareNext = append(compareNext, `EXCLUDED.weight_grams`)
	}
	if update.Note {
		setClauses = append(setClauses, `note = EXCLUDED.note`)
		compareCurrent = append(compareCurrent, `parcel.note`)
		compareNext = append(compareNext, `EXCLUDED.note`)
	}
	if update.Version {
		setClauses = append(setClauses, `version = EXCLUDED.version`)
		compareCurrent = append(compareCurrent, `parcel.version`)
		compareNext = append(compareNext, `EXCLUDED.version`)
	}

	results := make([]UpsertResult[*types.Parcel], 0, len(inputs))
	for start := 0; start < len(inputs); start += batch {
		chunk := inputs[start:min(start+batch, len(inputs))]
		prepared := chunk

		// The batch's rows, as CreateMany writes them.
		rows := make([][]batchInsertCell, 0, len(prepared))
		for _, input := range prepared {
			var row []batchInsertCell
			// Primary key: id. Schema-owned identities may supply a stable
			// UUID, matching CreateOne; a row without one takes the generated default.
			{
				cell := batchInsertCell{column: `id`}
				var zeroPrimaryKey types.IdentityUUID
				if primaryKey, ok := parcelUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
					cell.value, cell.set = primaryKey.ToUUID(), true
				}
				row = append(row, cell)
			}
			// Required field: trackingCode
			{
				cell := batchInsertCell{column: `tracking_code`, set: true}
				cell.value = input.TrackingCode
				row = append(row, cell)
			}
			// Required field: weightGrams
			{
				cell := batchInsertCell{column: `weight_grams`, set: true}
				cell.value = input.WeightGrams
				row = append(row, cell)
			}
			// Optional field: note
			{
				cell := batchInsertCell{column: `note`}
				if !reflect.ValueOf(input.Note).IsZero() {
					cell.value = input.Note
					cell.set = true
				}
				row = append(row, cell)
			}
			// Required field: version
			{
				cell := batchInsertCell{column: `version`, set: true}
				cell.value = input.Version
				row = append(row, cell)
			}

			// Relationship foreign key columns, matching CreateOne
			rows = append(rows, row)
		}
		fieldNames, valuePlaceholders, values := buildBatchInsert(rows)
		assignments := append([]string(nil), setClauses...)
		if len(setClauses) == 0 {
			// An update that names no field compares none, so its WHERE is
			// FALSE: it leaves each row as it is, its version, stamps and
			// history all, and reads it back below.
			assignments = append(assignments, key.keep)
		} else {
			// Each fence the update's columns advance moves on by one
			// (D118).
			assignments = append(assignments, fenceBumps(parcelFences, assignments)...)
		}
		query := fmt.Sprintf(
			`INSERT INTO parcel (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "tracking_code", "weight_grams", "note", "version", (xmax = 0) AS _inserted`,
			strings.Join(fieldNames, ", "),
			strings.Join(valuePlaceholders, ", "),
			key.conflict,
			strings.Join(assignments, ", "),
			upsertWhere(``, compareCurrent, compareNext, onlyIfChanged || len(setClauses) == 0),
		)
		returned, inserted, err := r.upsertReturned(ctx, query, values)
		if err != nil {
			return nil, err
		}

		// A row is its input's by the key's values; an input that sets none
		// of them, whose key the database generates, takes the next row whose
		// key no input holds, as the rows come back in the inputs' order.
		keys := make([]string, len(prepared))
		set := make([]bool, len(prepared))
		for i, input := range prepared {
			keys[i], set[i] = parcelKeyOf(on, input)
		}
		matcher := newUpsertMatcher(keys, set)
		matched := make([]*UpsertResult[*types.Parcel], len(prepared))
		for n, row := range returned {
			text, ok := parcelKeyOf(on, row)
			i := matcher.take(text, ok)
			if i < 0 {
				return nil, fmt.Errorf("orm: UpsertMany of Parcel wrote a row whose %s no input holds", string(on))
			}
			status := UpsertUnchanged
			if inserted[n] {
				status = UpsertInserted
			} else if len(setClauses) > 0 {
				status = UpsertUpdated
			}
			matched[i] = &UpsertResult[*types.Parcel]{Row: row, Status: status}
		}

		// A row it did not return is one it left as it was, when update
		// names no field or only if changed, which it reads back by its key,
		// or a deleted one.
		var left []int
		for i := range matched {
			if matched[i] == nil {
				left = append(left, i)
			}
		}
		if len(left) > 0 {
			if !onlyIfChanged && len(setClauses) > 0 {
				return nil, fmt.Errorf("the Parcel row that holds the %s of input %d is deleted: %w", string(on), start+left[0], ErrNotFound)
			}
			keyValues := make([][]any, len(left))
			wanted := make([]*types.Parcel, len(left))
			for n, i := range left {
				cells, ok := upsertCellValues(rows[i], key.columns)
				if !ok {
					return nil, fmt.Errorf("no Parcel row holds an unset %s: %w", string(on), ErrNotFound)
				}
				keyValues[n], wanted[n] = cells, prepared[i]
			}
			found, err := r.rowsOfKeys(ctx, on, keyValues, wanted)
			if err != nil {
				return nil, err
			}
			for n, i := range left {
				matched[i] = &UpsertResult[*types.Parcel]{Row: found[n], Status: UpsertUnchanged}
			}
		}
		for _, result := range matched {
			results = append(results, *result)
		}
	}
	return results, nil
}

// upsertReturned runs an upsert's statement, query with values, and scans
// each row it returns and whether it inserted it.
func (r *ParcelRepository) upsertReturned(ctx context.Context, query string, values []any) ([]*types.Parcel, []bool, error) {
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to execute upsert: %w", err)
	}
	defer rows.Close()
	var returned []*types.Parcel
	var inserted []bool
	for rows.Next() {
		var flag bool
		row, err := r.scanReturned(rows, &flag)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to scan result: %w", err)
		}
		returned = append(returned, row)
		inserted = append(inserted, flag)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("error iterating results: %w", err)
	}
	return returned, inserted, nil
}

// rowsOfKeys reads the rows that hold keys, each the values of the unique
// key on an input's insert binds, among the rows the key's index holds, in
// the inputs' order: the rows an upsert left as they were, as one whose
// update sets no field or one only if changed does (D89). A key no live
// row holds is ErrNotFound.
func (r *ParcelRepository) rowsOfKeys(ctx context.Context, on ParcelUniqueKey, keys [][]any, inputs []*types.Parcel) ([]*types.Parcel, error) {
	tuples, values := upsertKeyTuples(keys)
	query := fmt.Sprintf(parcelUniqueKeys[on].rows, strings.Join(tuples, ", "))
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the rows the upsert left: %w", err)
	}
	defer rows.Close()
	found := map[string]*types.Parcel{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := parcelKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.Parcel, len(inputs))
	for i, input := range inputs {
		text, _ := parcelKeyOf(on, input)
		row := found[text]
		if row == nil {
			return nil, fmt.Errorf("the Parcel row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
}

// heldOfKey reads the row that holds input's value of the unique key on,
// keyValues the values of the key's columns its insert binds, which an
// upsert left as it was: by rowsOfKeys, or, for a key over an expression,
// whose columns read no row, by the expression's value over keyValues
// (sqlutil.UniqueKey.Held, D105). A key no live row holds is ErrNotFound.
func (r *ParcelRepository) heldOfKey(ctx context.Context, on ParcelUniqueKey, keyValues []any, input *types.Parcel) (*types.Parcel, error) {
	query := parcelUniqueKeys[on].held
	if query == "" {
		found, err := r.rowsOfKeys(ctx, on, [][]any{keyValues}, []*types.Parcel{input})
		if err != nil {
			return nil, err
		}
		return found[0], nil
	}
	var read pgx.Row
	if r.tx != nil {
		read = r.tx.QueryRow(ctx, query, keyValues...)
	} else {
		read = r.db.pool.QueryRow(ctx, query, keyValues...)
	}
	row, err := r.scanReturned(read, nil)
	if err == pgx.ErrNoRows {
		return nil, fmt.Errorf("the Parcel row that holds the key %s is deleted: %w", string(on), ErrNotFound)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the row the upsert left: %w", err)
	}
	return row, nil
}

// CreateMany inserts multiple Parcel records in a single statement
func (r *ParcelRepository) CreateMany(ctx context.Context, inputs []*types.Parcel) ([]*types.Parcel, error) {
	if len(inputs) == 0 {
		return []*types.Parcel{}, nil
	}

	// Set audit fields

	// Build the batch INSERT in one pass over the fields. Each row records every
	// candidate column in the same order, with the value it binds or no value
	// when it leaves an optional column unset; buildBatchInsert inserts the
	// columns any row sets and writes DEFAULT for a row that leaves one unset.
	batch := make([][]batchInsertCell, 0, len(inputs))
	for _, input := range inputs {
		var row []batchInsertCell
		// Primary key: id. Schema-owned identities may supply a stable
		// UUID, matching CreateOne; a row without one takes the generated default.
		{
			cell := batchInsertCell{column: `id`}
			var zeroPrimaryKey types.IdentityUUID
			if primaryKey, ok := parcelUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
				cell.value, cell.set = primaryKey.ToUUID(), true
			}
			row = append(row, cell)
		}
		// Required field: trackingCode
		{
			cell := batchInsertCell{column: `tracking_code`, set: true}
			cell.value = input.TrackingCode
			row = append(row, cell)
		}
		// Required field: weightGrams
		{
			cell := batchInsertCell{column: `weight_grams`, set: true}
			cell.value = input.WeightGrams
			row = append(row, cell)
		}
		// Optional field: note
		{
			cell := batchInsertCell{column: `note`}
			if !reflect.ValueOf(input.Note).IsZero() {
				cell.value = input.Note
				cell.set = true
			}
			row = append(row, cell)
		}
		// Required field: version
		{
			cell := batchInsertCell{column: `version`, set: true}
			cell.value = input.Version
			row = append(row, cell)
		}

		// Relationship foreign key columns, matching CreateOne
		batch = append(batch, row)
	}
	fieldNames, valuePlaceholders, values := buildBatchInsert(batch)

	// Build RETURNING clause with explicit column order matching scan order (using OrderedMembers for schema order)
	returningClauseMany := `"id", "tracking_code", "weight_grams", "note", "version"`
	query := fmt.Sprintf(
		`INSERT INTO parcel (%s) VALUES %s RETURNING %s`,
		strings.Join(fieldNames, ", "),
		strings.Join(valuePlaceholders, ", "),
		returningClauseMany,
	)

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute batch insert: %w", err)
	}
	defer rows.Close()

	// Scan results
	results := []*types.Parcel{}
	for rows.Next() {
		result := &types.Parcel{}
		// Create temporary variables for nullable fields that need pointer scanning

		var tempNote sql.NullString

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&result.Id,

			&result.TrackingCode,

			&result.WeightGrams,

			&tempNote,

			&result.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}

		// Copy nullable fields when present

		if tempNote.Valid {
			result.Note = tempNote.String
		}

		// Set relationship IDs from scanned FK values
		results = append(results, result)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}

	return results, nil
}

